const CODE_TO_LANG: Record<string, LangId> = {
  'te-IN': 'te',
  'hi-IN': 'hi',
  'ta-IN': 'ta',
  'kn-IN': 'kn',
  'ml-IN': 'ml',
  'mr-IN': 'mr',
  'gu-IN': 'gu',
  'bn-IN': 'bn',
  'pa-IN': 'pa',
  'or-IN': 'or',
  'as-IN': 'as',
  'ur-IN': 'ur',
};

export function phrasesFor(locale: string): Record<string, string> {
  const lang = CODE_TO_LANG[locale];
  if (!lang) return {};
  const out: Record<string, string> = {};
  for (const [en, row] of Object.entries(T)) {
    const val = row[lang];
    if (val) out[en] = val;
  }
  return out;
}
